<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ubah Soal — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:#f4f7fb}.wrap{max-width:850px;margin:auto}.back{display:inline-block;padding:10px 13px;border-radius:10px;background:#fff;color:#23395d;text-decoration:none;font-weight:800}.head{margin:17px 0;padding:26px 28px;border-radius:21px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.head h1{margin:0 0 6px}.head p{margin:0;color:#e7effa}.box{padding:24px;background:#fffd;border:1px solid #fff;border-radius:18px;box-shadow:0 14px 30px #23395d12}.field{display:grid;gap:7px;margin:14px 0}.field label{font-size:12px;font-weight:800;color:#475569}input,textarea,select{width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:11px;font:inherit}textarea{min-height:120px}.option{display:grid;grid-template-columns:35px 1fr auto;gap:7px;align-items:center;margin:8px 0}.letter{display:grid;place-items:center;height:39px;border-radius:8px;background:#e8eef7;color:#23395d;font-weight:800}.option button{border:0;border-radius:8px;padding:9px;background:#fee2e2;color:#991b1b;cursor:pointer}.button{border:0;border-radius:10px;padding:11px 15px;background:#23395d;color:#fff;font-weight:800;cursor:pointer}.secondary{background:#e8eef7;color:#23395d}.error{color:#b91c1c;font-size:13px}</style></head><body><main class="wrap"><a class="back" href="{{ route('teacher.questions') }}">← Bank Soal</a><section class="head"><h1>Perbarui Soal</h1><p>Tambah atau hapus opsi jawaban sesuai kebutuhan.</p></section><section class="box"><form method="post" action="{{ route('teacher.questions.update',$question->id) }}">@csrf @method('PUT')<div class="field"><label>MATA PELAJARAN</label><input name="subject" value="{{ old('subject',$question->subject) }}" required></div><div class="field"><label>PERTANYAAN</label><textarea name="question_text" required>{{ old('question_text',$question->question_text) }}</textarea></div><div class="field"><label>PILIHAN JAWABAN</label><div id="options">@foreach($choices as $letter=>$choice)<div class="option"><span class="letter">{{ $letter }}</span><input name="choices[]" value="{{ $choice }}" required><button type="button">×</button></div>@endforeach</div><button type="button" class="button secondary" id="add">+ Tambah Opsi</button></div><div class="field"><label>JAWABAN BENAR</label><select name="correct_answer" id="correct"></select></div><div class="field"><label>BOBOT NILAI</label><input type="number" name="weight" value="{{ old('weight',$question->weight) }}" min="1" max="100" required></div>@foreach($errors->all() as $error)<p class="error">{{ $error }}</p>@endforeach<button class="button">Simpan Perubahan</button></form></section></main><template id="option"><div class="option"><span class="letter"></span><input name="choices[]" required><button type="button">×</button></div></template><script>const list=document.querySelector('#options'),add=document.querySelector('#add'),select=document.querySelector('#correct'),current=@json(old('correct_answer',$question->correct_answer));function sync(){const rows=[...list.children];select.innerHTML='';rows.forEach((row,i)=>{const letter=String.fromCharCode(65+i);row.querySelector('.letter').textContent=letter;row.querySelector('button').hidden=rows.length<=2;const opt=new Option(letter,letter,letter===current);select.add(opt);row.querySelector('button').onclick=()=>{row.remove();sync()}})}add.onclick=()=>{if(list.children.length>=26)return;list.append(document.querySelector('#option').content.firstElementChild.cloneNode(true));sync()};sync()</script></body></html>
